use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut first = true
    let mut width = 0
    let mut bad = false
    let mut line = ""
    let mut cur = 0
    for l in text.lines() {
        if first {
            first = false
            match l.trim().parse::<int>() {
                Ok(n) => {
                    if n <= 0 { bad = true }
                    width = n
                }
                Err(_) => { bad = true }
            }
            if bad {
                println("error: bad width")
                std::process::exit(1)
            }
        } else {
            for w in l.split_whitespace() {
                let n: int = w.len() as int
                if cur == 0 {
                    line = w
                    cur = n
                } else if cur + 1 + n <= width {
                    line = "${line} ${w}"
                    cur = cur + 1 + n
                } else {
                    println(line)
                    line = w
                    cur = n
                }
            }
        }
    }
    if first {
        println("error: bad width")
        std::process::exit(1)
    }
    if cur > 0 { println(line) }
}

